<?php
namespace App\Http\Controllers\Api\Reports\Purchases;use App\Exports\PurchasesReportExport;use App\Http\Controllers\Controller;use App\Services\Reports\Purchases\PurchasesReportService;use App\Services\Reports\ReportExportService;use Illuminate\Http\Request;
class PurchasesReportController extends Controller{public function __construct(private readonly PurchasesReportService $service,private readonly ReportExportService $exports){}public function index(Request $r){return response()->json($this->service->generate($this->filters($r)));}public function options(){return response()->json($this->service->options());}public function pdf(Request $r){$report=$this->service->generate($this->filters($r));return$this->exports->pdf('reports.purchases.list.pdf',compact('report'),'listado-compras-'.now()->format('Ymd-His').'.pdf');}public function export(Request $r){$f=$this->filters($r,true);$format=$f['format'];unset($f['format']);$report=$this->service->generate($f);return$this->exports->spreadsheet(new PurchasesReportExport($this->service->exportRows($report)),'listado-compras-'.now()->format('Ymd-His').'.'.$format,$format);}private function filters(Request $r,bool $e=false):array{$rules=['date_from'=>['required','date'],'date_to'=>['required','date','after_or_equal:date_from'],'branches'=>['nullable','array'],'branches.*'=>['string','max:255'],'operation_types'=>['nullable','array'],'operation_types.*'=>['string','max:100'],'provider_ids'=>['nullable','array'],'provider_ids.*'=>['integer','exists:providers,id'],'provinces'=>['nullable','array'],'provinces.*'=>['string','max:100']];if($e)$rules['format']=['required','in:xlsx,csv'];return$r->validate($rules);}}
